if(path==="import-history"&&method==="POST"){
  const regions=[
    ["region_sambas","Kabupaten Sambas","Kabupaten"],
    ["region_bengkayang","Kabupaten Bengkayang","Kabupaten"],
    ["region_landak","Kabupaten Landak","Kabupaten"],
    ["region_mempawah","Kabupaten Mempawah","Kabupaten"],
    ["region_sanggau","Kabupaten Sanggau","Kabupaten"],
    ["region_ketapang","Kabupaten Ketapang","Kabupaten"],
    ["region_sintang","Kabupaten Sintang","Kabupaten"],
    ["region_kapuas_hulu","Kabupaten Kapuas Hulu","Kabupaten"],
    ["region_sekadau","Kabupaten Sekadau","Kabupaten"],
    ["region_melawi","Kabupaten Melawi","Kabupaten"],
    ["region_kayong_utara","Kabupaten Kayong Utara","Kabupaten"],
    ["region_kubu_raya","Kabupaten Kubu Raya","Kabupaten"],
    ["region_pontianak","Kota Pontianak","Kota"],
    ["region_singkawang","Kota Singkawang","Kota"]
  ];
  const existingRows=await query(project,access,"history_posts",null,null,5000);
  const existingById=new Map(existingRows.map(x=>[x.id,x.data]));
  const titles=regions.map(x=>x[1]).join("|");
  const source=new URL("https://id.wikipedia.org/w/api.php");
  source.search=new URLSearchParams({action:"query",format:"json",formatversion:"2",prop:"extracts|pageimages",explaintext:"1",piprop:"original|thumbnail",pithumbsize:"1000",redirects:"1",titles}).toString();
  const response=await fetch(source.toString(),{headers:{"accept":"application/json","user-agent":"KalbarKiteAdmin/1.0 (history content import)"}});
  if(!response.ok)throw Object.assign(Error("Wikipedia tidak dapat diakses (HTTP "+response.status+")."),{status:502});
  const payload=await response.json(),pages=payload.query?.pages||[];
  const normalize=value=>String(value||"").toLowerCase().replace(/^(kabupaten|kota)\s+/,"").replace(/[^a-z0-9]/g,"");
  const byTitle=new Map(pages.map(page=>[normalize(page.title),page]));
  const writes=[],failures=[];
  for(const [id,title,kind] of regions){
    let page=byTitle.get(normalize(title));
    if(!page||page.missing||!String(page.extract||"").trim()){
      const one=new URL("https://id.wikipedia.org/w/api.php");
      one.search=new URLSearchParams({action:"query",format:"json",formatversion:"2",prop:"extracts|pageimages",explaintext:"1",piprop:"original|thumbnail",pithumbsize:"1000",redirects:"1",titles:title}).toString();
      try{
        const fallback=await fetch(one.toString(),{headers:{"accept":"application/json","user-agent":"KalbarKiteAdmin/1.0 (history content import)"}});
        if(fallback.ok){const data=await fallback.json();page=(data.query?.pages||[]).find(item=>!item.missing&&String(item.extract||"").trim())||page;}
      }catch(_){}
    }
    const extract=String(page?.extract||"").trim();
    if(!page||page.missing||!extract){failures.push({region:title,reason:"Artikel sumber tidak ditemukan atau tidak memiliki ringkasan"});continue}
    const previous=existingById.get(id)||{};
    const thumb=page.thumbnail?.source||page.original?.source||previous.imageUrl||"";
    const sourceUrl="https://id.wikipedia.org/wiki/"+encodeURIComponent(String(page.title||title).replace(/ /g,"_"));
    writes.push({id,data:{...previous,id,title,pageTitle:page.title||title,kind,body:extract,imageUrl:thumb,sourceName:"Wikipedia bahasa Indonesia",sourceUrl,status:previous.status||"published",updatedAt:new Date().toISOString(),createdAt:previous.createdAt||new Date().toISOString()}});
  }
  const imported=await commitDocs(project,access,"history_posts",writes);
  await audit(project,access,actor,"import_history","history_posts",{imported,missing:failures.length,failures});
  return json({ok:failures.length===0,imported,missing:failures.length,total:regions.length,stored:existingRows.length+imported,complete:failures.length===0,failures});
}
